python3 -I - <<'PY'
import re, ast, pathlib, statistics, datetime
p=pathlib.Path('/user/user1/harbor-runs/c166a6a54b94/workspace/outputs/driver.log')
roll=[]; perf=[]; rec=[]; train=[]
for n,line in enumerate(p.open(errors='replace'),1):
    m=re.search(r'\[([\d-]+ [\d:.]+).*log_utils\.py:66 - rollout (\d+): (\{.*\})',line)
    if m:
        d=ast.literal_eval(m.group(3)); roll.append((n,int(m.group(2)),datetime.datetime.fromisoformat(m.group(1)),d)); continue
    m=re.search(r'train_metric_utils\.py:50 - perf (\d+): (\{.*\})',line)
    if m:
        d=ast.literal_eval(m.group(2)); perf.append((int(m.group(1)),d)); continue
    if 'recycled' in line and 'rollout/' in line:
        rec.append((n,line.strip()))
    m=re.search(r'log_utils\.py:66 - train (\d+): (\{.*\})',line)
    if m: train.append((int(m.group(1)),ast.literal_eval(m.group(2))))
print('counts roll perf recycle train',len(roll),len(perf),len(rec),len(train))
print('first/last rollout times',roll[0][2],roll[-1][2], 'span_min',(roll[-1][2]-roll[0][2]).total_seconds()/60)
for lo,hi in [(0,9),(10,19),(40,49),(50,59),(80,91)]:
    rr=[d for _,i,_,d in roll if lo<=i<=hi]
    print(f'roll {lo}-{hi}: n={len(rr)} raw={statistics.mean(d["rollout/raw_reward"] for d in rr):.5f} acc_est={(1+statistics.mean(d["rollout/raw_reward"] for d in rr))/2:.5f} len={statistics.mean(d["rollout/response_lengths"] for d in rr):.1f} trunc={statistics.mean(d["rollout/truncated"] for d in rr):.4f}')
print('\nSelected perf:')
for i,d in perf:
    if i in [0,1,10,30,45,46,60,75,90,91]: print(i,d)
if perf:
    keys=['perf/step_time','perf/train_wait_time','perf/train_time','perf/actor_train_time','perf/ref_log_probs_time','perf/log_probs_time','perf/update_weights_time','perf/wait_time_ratio','perf/actor_train_tok_per_s']
    print('\nPerf summaries:')
    for k in keys:
        a=[d[k] for _,d in perf if k in d]
        if a: print(k,'mean',round(statistics.mean(a),4),'first10',round(statistics.mean(a[:10]),4),'last10',round(statistics.mean(a[-10:]),4),'min',round(min(a),4),'max',round(max(a),4))
print('\nTrain metric keys', train[0][1].keys() if train else None)
for i,d in train[:2]+train[-2:]: print(i,d)
print('\nLast 8 recycling lines:')
for x in rec[-8:]: print(*x)
PY

