import pathlib,re,ast,statistics,collections,math
p=pathlib.Path('/user/user1/harbor-runs/c166a6a54b94/workspace/outputs/driver.log')
steps={}; rp={}
for n,line in enumerate(p.open(errors='replace'),1):
 m=re.search(r'log_utils\.py:460 - step (\d+): (\{.*\})',line)
 if m: steps[int(m.group(1))]=ast.literal_eval(m.group(2))
 m=re.search(r'metrics\.py:79 - perf (\d+): (\{.*\})',line)
 if m: rp[int(m.group(1))]=ast.literal_eval(m.group(2))
print('optimization steps',len(steps),'range',min(steps),max(steps))
keys=['train/loss','train/pg_loss','train/pg_clipfrac','train/ppo_kl','train/ess_ratio','train/train_rollout_logprob_abs_diff','train/train_rollout_kl','train/tis','train/tis_clipfrac','train/tis_abs','train/grad_norm']
for k in keys:
 a=[d[k] for i,d in sorted(steps.items()) if k in d and math.isfinite(d[k])]
 print(k,'first10',float(statistics.mean(a[:10])),'last10',float(statistics.mean(a[-10:])),'min',min(a),'max',max(a),'nonfinite',len(steps)-len(a))
print('grad > clip',sum(d.get('train/grad_norm',0)>1 for d in steps.values()),'zero grad',sum(d.get('train/grad_norm',0)==0 for d in steps.values()))
print('recycle distribution',collections.Counter(d['rollout/fully_async/stale_groups_recycled'] for d in rp.values()))
print('special recycle steps',[(i,d['rollout/fully_async/stale_groups_recycled']) for i,d in sorted(rp.items()) if d['rollout/fully_async/stale_groups_recycled']!=32])
for i in [0,1,45,90,91]: print('step',i,'train',steps.get(i))
PY

