        # staleness check, so it works even without a queryable version endpoint.
        for s in _iter_samples(group):
            for v in s.weight_versions:
                if str(v).isdigit():
                    self._weight_version.observe(int(v))

        if args.max_weight_staleness is not None:
            oldest = group_oldest_weight_version(group)
            current = await self._weight_version.get(args)
            if oldest is not None and current is not None:
                staleness = current - oldest
                staleness_values.append(staleness)
                if staleness > args.max_weight_staleness:
                    self._recycle(prompt_group)
                    stale_groups_recycled += 1
                    logger.info(
                        f"Recycled stale group (oldest_version={oldest}, current={current}, "
                        f"staleness={staleness} > max={args.max_weight_staleness})"
                    )
                    continue

        filter_output = call_dynamic_filter(self._dynamic_filter, args, group)
        if not filter_output.keep:
            # Dropped, not recycled: no usable gradient signal.
            metric_gatherer.on_dynamic_filter_drop(reason=filter_output.reason)
            continue

        if do_print:
            sample = _first_sample(group)
            logger.info(
                f"First rollout sample: {[str(sample.prompt) + sample.response]}, "
                f"label: {sample.label}, reward: {sample.reward}"
            )
            do_print = False

        data.append(group)

    sample = _first_sample(data[-1])
    logger.info(
        f"Finish rollout: {[str(sample.prompt) + sample.response]}, "
        f"label: {sample.label}, reward: {sample.reward}"
    )

    data.sort(key=lambda group: _first_sample(group).index)

    if self._sample_filter is not None:
        self._sample_filter(args, data)

    metrics = {
        "rollout/fully_async/queue_size": self._output.qsize(),
        "rollout/fully_async/aborted_groups_recycled": aborted_groups_recycled,
        "rollout/fully_async/stale_groups_recycled": stale_groups_recycled,
        **metric_gatherer.collect(),
    }
    if staleness_values:
        metrics["rollout/fully_async/avg_staleness"] = sum(staleness_values) / len(staleness_values)
        metrics["rollout/fully_async/max_staleness"] = max(staleness_values)

    return RolloutFnTrainOutput(samples=data, metrics=metrics)

def _recycle(self, prompt_group: list[Sample]) -> None:
    for sample in prompt_group:
        sample.reset_for_retry()
    self.data_source.add_samples([prompt_group])

    x = metadata.get("dynamic_global_batch_size")
    assert args.use_dynamic_global_batch_size == (x is not None)
    if x is not None:
        train_data["dynamic_global_batch_size"] = x

    return train_data


def _post_process_rewards(
    args,
    samples: list[Sample] | list[list[Sample]],
    custom_reward_post_process_func,
    prompt_group_sizes: list[int] | None = None,
):
    if (f := custom_reward_post_process_func) is not None:
        return f(args, samples)

    raw_rewards = [sample.get_reward_value(args) for sample in samples]
    if args.advantage_estimator in ["grpo", "gspo", "reinforce_plus_plus_baseline"] and args.rewards_normalization:
        # group norm
        rewards = torch.tensor(raw_rewards, dtype=torch.float)
        if prompt_group_sizes is not None:
            # Multi-LoRA: groups may have heterogeneous sizes (per-adapter
            # n_samples_per_prompt), so normalize within explicit boundaries.
            assert sum(prompt_group_sizes) == len(
                raw_rewards
            ), f"prompt group sizes sum to {sum(prompt_group_sizes)}, but got {len(raw_rewards)} rewards"
            normalized_groups = []
            for group_rewards in rewards.split(prompt_group_sizes):
                centered = group_rewards - group_rewards.mean()
                if (
                    args.advantage_estimator in ["grpo", "gspo"]
                    and args.grpo_std_normalization
                    and group_rewards.numel() > 1
                ):
                    centered = centered / (group_rewards.std() + 1e-6)
                normalized_groups.append(centered)
            return raw_rewards, torch.cat(normalized_groups).tolist()
        if rewards.shape[-1] == args.n_samples_per_prompt * args.rollout_batch_size:
            rewards = rewards.reshape(-1, args.n_samples_per_prompt)
        else:
            # when samples count are not equal in each group
            rewards = rewards.view(-1, rewards.shape[-1])
        mean = rewards.mean(dim=-1, keepdim=True)
        rewards = rewards - mean

        if args.advantage_estimator in ["grpo", "gspo"] and args.grpo_std_normalization:
            std = rewards.std(dim=-1, keepdim=True)
            rewards = rewards / (std + 1e-6)

        return raw_rewards, rewards.flatten().tolist()

    return raw_rewards, raw_rewards


